1	// Command ledger 是本地器具校准台账的命令行入口。
2	//
3	// 用法：
4	//
5	//	ledger -f 台账文件.json <子命令> [参数]
6	//
7	// 数据只保存在 -f 指定的本机文件中；不指定时使用当前目录下的 ledger.json。
8	// 不同文件是互不混入的不同台账，退出后再次打开同一文件可继续查询和操作。
9	package main
10	
11	import (
12		"encoding/json"
13		"errors"
14		"flag"
15		"fmt"
16		"io"
17		"math"
18		"os"
19		"strconv"
20		"strings"
21	
22		"github.com/bengzyyys/calibration-ledger/calibrate"
23	)
24	
25	const usageText = `本地器具校准台账（仅本机，不连接真实实验室）
26	
27	用法：
28	  ledger -f <台账文件> [--json] <子命令> [参数]
29	
30	子命令：
31	  register   登记器具：--id 编号 --name 名称 --allowed 允许绝对误差
32	  status     切换状态：--id 编号 --status 在用|停用|待校准
33	  cert       录入证书：--instrument 器具编号 --number 证书编号 \
34	             --cal-date YYYY-MM-DD --expiry YYYY-MM-DD \
35	             --method 方法 --error 测得误差 --summary 摘要
36	  use        申请使用器具：--id 编号（允许与拒绝都会留痕）
37	  review     按器具核对：--id 编号
38	  list       列出全部登记器具
39	  plan       建立校准计划：--instrument 器具编号 --number 计划编号 \
40	             --date YYYY-MM-DD --note 非空说明
41	  reschedule 计划改期：--number 计划编号 --date 新日期 --reason 非空原因
42	  cancel     取消计划：--number 计划编号 --reason 非空原因
43	  complete   用证书完成计划：--number 计划编号 --certificate 证书编号
44	  todos      校准待办：[--instrument 器具编号]（默认全部未结束计划）
45	
46	通用参数：
47	  -f, --file   台账文件路径（默认 ledger.json）
48	      --json   以 JSON 输出结果
49	
50	退出码：0 成功；1 业务拒绝或未找到；2 参数或读写错误。
51	`
52	
53	// options 是所有子命令共用的全局参数。
54	type options struct {
55		file   string
56		asJSON bool
57	}
58	
59	func main() {
60		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
61	}
62	
63	func run(args []string, stdout, stderr io.Writer) int {
64		if len(args) == 0 {
65			fmt.Fprint(stderr, usageText)
66			return 2
67		}
68		var opts options
69		fileSet := false
70		cmd := ""
71		businessArgs := make([]string, 0, len(args))
72		// 全局参数（-f/--file、--json）既可以写在子命令前，也可以与器具编号、
73		// 证书编号等业务参数交错写在子命令之后。这里先从左到右扫描整条命令行，
74		// 剥除全局参数并确定最终台账路径，再打开该文件：因此 -f 出现的位置不会
75		// 改变它选中的台账；同一次调用出现多个文件参数时，短名与长名共同参与
76		// 从左到右的顺序，以最后一次明确给出的路径为准。
77		// 子命令的业务标志（--method、--summary 等）都需要值：不带等号时紧跟的
78		// 下一个参数就是它的值。值必须原样保留为字段内容——即使它看起来是
79		// -f、--file=…、-f… 或 --json，也不参与台账选择与输出格式设置；
80		// 只有出现在完整字段之外（或子命令之前）的同名写法才是全局参数。
81		for i := 0; i < len(args); i++ {
82			a := args[i]
83			if cmd == "" && !strings.HasPrefix(a, "-") {
84				// 第一个不以“-”开头的参数是子命令；其后的位置参数仍要继续扫描。
85				cmd = a
86				continue
87			}
88			switch {
89			case a == "-f" || a == "--file" || a == "-file":
90				if i+1 >= len(args) {
91					fmt.Fprintf(stderr, "%s 需要一个值\n", a)
92					return 2
93				}
94				i++
95				opts.file = args[i]
96				fileSet = true
97			case strings.HasPrefix(a, "--file="):
98				opts.file = a[len("--file="):]
99				fileSet = true
100			case strings.HasPrefix(a, "-file="):
101				opts.file = a[len("-file="):]
102				fileSet = true
103			case strings.HasPrefix(a, "-f="):
104				opts.file = strings.TrimPrefix(a, "-f=")
105				fileSet = true
106			case strings.HasPrefix(a, "-f") && len(a) > 2:
107				opts.file = a[2:]
108				fileSet = true
109			case a == "--json" || a == "-json":
110				opts.asJSON = true
111			case a == "--" && cmd != "":
112				// “--” 终止后续标志解析：其后的参数原样交给子命令
113				// （与此前 flag 包的行为一致），即使其中出现 -f 也不再视为全局参数。
114				businessArgs = append(businessArgs, args[i:]...)
115				i = len(args)
116			default:
117				if cmd == "" {
118					fmt.Fprintf(stderr, "未知全局参数 %s\n\n%s", a, usageText)
119					return 2
120				}
121				businessArgs = append(businessArgs, a)
122				// 业务标志不带等号时，下一个参数是它的字段值：原样一并转交子命令，
123				// 绝不再按全局参数解释（与 flag 包对字符串标志的取值行为一致）。
124				// 值缺失时不在这里补，由子命令解析时报“标志需要值”。
125				if strings.HasPrefix(a, "-") && !strings.Contains(a, "=") && i+1 < len(args) {
126					i++
127					businessArgs = append(businessArgs, args[i])
128				}
129			}
130		}
131		if fileSet {
132			if strings.TrimSpace(opts.file) == "" {
133				fmt.Fprintln(stderr, "台账文件路径不能为空或只有空白")
134				return 2
135			}
136		} else {
137			opts.file = "ledger.json"
138		}
139		if cmd == "" {
140			fmt.Fprint(stderr, usageText)
141			return 2
142		}
143		cmdArgs := businessArgs
144		if cmd == "help" || cmd == "-h" || cmd == "--help" {
145			fmt.Fprint(stdout, usageText)
146			return 0
147		}
148	
149		// 最终路径确定之后才打开台账：被后续 -f 覆盖掉的旧路径与默认文件
150		// 即使损坏或不可读，也不会影响对有效目标文件的操作。
151		l, err := calibrate.Open(opts.file)
152		if err != nil {
153			fmt.Fprintln(stderr, "打开台账失败：", err)
154			return 2
155		}
156	
157		switch cmd {
158		case "register":
159			return cmdRegister(l, cmdArgs, opts, stdout, stderr)
160		case "status":
161			return cmdStatus(l, cmdArgs, opts, stdout, stderr)
162		case "cert":
163			return cmdCert(l, cmdArgs, opts, stdout, stderr)
164		case "use":
165			return cmdUse(l, cmdArgs, opts, stdout, stderr)
166		case "review":
167			return cmdReview(l, cmdArgs, opts, stdout, stderr)
168		case "list":
169			return cmdList(l, cmdArgs, opts, stdout, stderr)
170		case "plan":
171			return cmdPlan(l, cmdArgs, opts, stdout, stderr)
172		case "reschedule":
173			return cmdReschedule(l, cmdArgs, opts, stdout, stderr)
174		case "cancel":
175			return cmdCancel(l, cmdArgs, opts, stdout, stderr)
176		case "complete":
177			return cmdComplete(l, cmdArgs, opts, stdout, stderr)
178		case "todos":
179			return cmdTodos(l, cmdArgs, opts, stdout, stderr)
180		default:
181			fmt.Fprintf(stderr, "未知子命令 %q\n\n%s", cmd, usageText)
182			return 2
183		}
184	}
185	
186	// newFlagSet 构造子命令自己的标志集。台账文件与 --json 已在打开台账前
187	// 从整条命令行统一解析，这里只保留 --json 的登记，绝不在此处重新登记
188	// -f/--file：否则子命令后的文件参数会指向与已打开台账不同的路径。
189	func newFlagSet(name string, opts *options) *flag.FlagSet {
190		fs := flag.NewFlagSet(name, flag.ContinueOnError)
191		fs.SetOutput(io.Discard)
192		fs.BoolVar(&opts.asJSON, "json", opts.asJSON, "以 JSON 输出")
193		return fs
194	}
195	
196	func parseFloat(stderr io.Writer, raw, field string) (float64, bool) {
197		v, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
198		if err != nil || math.IsNaN(v) || math.IsInf(v, 0) {
199			fmt.Fprintf(stderr, "%s 必须是有限数字\n", field)
200			return 0, false
201		}
202		return v, true
203	}
204	
205	func emit(opts options, stdout, stderr io.Writer, human string, v any) int {
206		if opts.asJSON {
207			raw, err := json.MarshalIndent(v, "", "  ")
208			if err != nil {
209				fmt.Fprintln(stderr, "输出 JSON 失败：", err)
210				return 2
211			}
212			fmt.Fprintln(stdout, string(raw))
213			return 0
214		}
215		fmt.Fprint(stdout, human)
216		return 0
217	}
218	
219	// failBusiness 处理业务拒绝：退出码 1，原记录未被改动。
220	func failBusiness(opts options, stdout, stderr io.Writer, err error, rejected any) int {
221		if opts.asJSON {
222			raw, _ := json.MarshalIndent(rejected, "", "  ")
223			fmt.Fprintln(stdout, string(raw))
224		}
225		fmt.Fprintln(stderr, "已拒绝：", err)
226		return 1
227	}
228	
229	func failIO(stderr io.Writer, err error) int {
230		fmt.Fprintln(stderr, "操作失败：", err)
231		return 2
232	}
233	
234	func cmdRegister(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
235		fs := newFlagSet("register", &opts)
236		id := fs.String("id", "", "器具唯一编号")
237		name := fs.String("name", "", "器具名称")
238		allowed := fs.String("allowed", "", "允许的绝对误差（不小于零的有限数）")
239		if err := fs.Parse(args); err != nil {
240			fmt.Fprintln(stderr, "register 参数错误：", err)
241			return 2
242		}
243		if *id == "" || *name == "" || *allowed == "" {
244			fmt.Fprintln(stderr, "register 必须提供 --id、--name、--allowed")
245			return 2
246		}
247		allowedErr, ok := parseFloat(stderr, *allowed, "允许的绝对误差")
248		if !ok {
249			return 2
250		}
251		inst, err := l.Register(calibrate.RegisterInput{
252			ID: *id, Name: *name, AllowedError: allowedErr,
253		})
254		if err != nil {
255			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
256				return failBusiness(opts, stdout, stderr, err,
257					map[string]any{"accepted": false, "error": err.Error()})
258			}
259			return failIO(stderr, err)
260		}
261		human := fmt.Sprintf("已登记器具 %s（%s），允许绝对误差 %g，状态：%s\n",
262			inst.ID, inst.Name, inst.AllowedError, inst.Status)
263		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "instrument": inst})
264	}
265	
266	func cmdStatus(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
267		fs := newFlagSet("status", &opts)
268		id := fs.String("id", "", "器具编号")
269		status := fs.String("status", "", "在用|停用|待校准")
270		if err := fs.Parse(args); err != nil {
271			fmt.Fprintln(stderr, "status 参数错误：", err)
272			return 2
273		}
274		if *id == "" || *status == "" {
275			fmt.Fprintln(stderr, "status 必须提供 --id、--status")
276			return 2
277		}
278		st, err := calibrate.ParseStatus(*status)
279		if err != nil {
280			fmt.Fprintln(stderr, err)
281			return 2
282		}
283		if err := l.SetStatus(*id, st); err != nil {
284			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
285				return failBusiness(opts, stdout, stderr, err,
286					map[string]any{"accepted": false, "error": err.Error()})
287			}
288			return failIO(stderr, err)
289		}
290		human := fmt.Sprintf("器具 %s 已切换为%s\n", *id, st)
291		return emit(opts, stdout, stderr, human,
292			map[string]any{"accepted": true, "id": *id, "status": st})
293	}
294	
295	func cmdCert(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
296		fs := newFlagSet("cert", &opts)
297		instrument := fs.String("instrument", "", "器具编号")
298		number := fs.String("number", "", "证书编号（全台账唯一）")
299		calDate := fs.String("cal-date", "", "校准日期 YYYY-MM-DD")
300		expiry := fs.String("expiry", "", "有效期截止日 YYYY-MM-DD")
301		method := fs.String("method", "", "校准方法")
302		measured := fs.String("error", "", "测得误差（有限数）")
303		summary := fs.String("summary", "", "证书摘要")
304		if err := fs.Parse(args); err != nil {
305			fmt.Fprintln(stderr, "cert 参数错误：", err)
306			return 2
307		}
308		missing := []string{}
309		for k, v := range map[string]string{
310			"--instrument": *instrument, "--number": *number, "--cal-date": *calDate,
311			"--expiry": *expiry, "--method": *method, "--error": *measured, "--summary": *summary,
312		} {
313			if strings.TrimSpace(v) == "" {
314				missing = append(missing, k)
315			}
316		}
317		if len(missing) > 0 {
318			fmt.Fprintln(stderr, "cert 缺少必填参数：", strings.Join(missing, "、"))
319			return 2
320		}
321		measuredErr, ok := parseFloat(stderr, *measured, "测得误差")
322		if !ok {
323			return 2
324		}
325		cert, duplicate, err := l.AddCertificate(calibrate.CertificateInput{
326			InstrumentID: *instrument,
327			Number:       *number,
328			CalDate:      *calDate,
329			Expiry:       *expiry,
330			Method:       *method,
331			Error:        measuredErr,
332			Summary:      *summary,
333		})
334		if err != nil {
335			if calibrate.IsValidation(err) || calibrate.IsConflict(err) || errors.Is(err, calibrate.ErrNotFound) {
336				return failBusiness(opts, stdout, stderr, err,
337					map[string]any{"accepted": false, "conflict": calibrate.IsConflict(err), "error": err.Error()})
338			}
339			return failIO(stderr, err)
340		}
341		note := "已录入新证书"
342		if duplicate {
343			note = "同号证书且内容一致，返回原证书，未增加历史记录"
344		}
345		verdict := "合格"
346		if math.Abs(cert.Error) > allowedErrorOf(l, cert.InstrumentID) {
347			verdict = "超差"
348		}
349		human := fmt.Sprintf("%s：%s（器具 %s，校准日期 %s，截止日 %s，测得误差 %g，判定：%s）\n",
350			note, cert.Number, cert.InstrumentID, cert.CalDate, cert.Expiry, cert.Error, verdict)
351		return emit(opts, stdout, stderr, human,
352			map[string]any{"accepted": true, "duplicate": duplicate, "verdict": verdict, "certificate": cert})
353	}
354	
355	func allowedErrorOf(l *calibrate.Ledger, id string) float64 {
356		r, err := l.Review(id)
357		if err != nil {
358			return 0
359		}
360		return r.Instrument.AllowedError
361	}
362	
363	func cmdUse(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
364		fs := newFlagSet("use", &opts)
365		id := fs.String("id", "", "器具编号")
366		if err := fs.Parse(args); err != nil {
367			fmt.Fprintln(stderr, "use 参数错误：", err)
368			return 2
369		}
370		if strings.TrimSpace(*id) == "" {
371			fmt.Fprintln(stderr, "use 必须提供 --id")
372			return 2
373		}
374		d, err := l.RequestUse(*id)
375		if err != nil {
376			if errors.Is(err, calibrate.ErrNotFound) || calibrate.IsValidation(err) {
377				return failBusiness(opts, stdout, stderr, err,
378					map[string]any{"accepted": false, "recorded": false, "error": err.Error()})
379			}
380			return failIO(stderr, err)
381		}
382		if !d.Allowed {
383			var sb strings.Builder
384			sb.WriteString(fmt.Sprintf("拒绝使用器具 %s，已记录本次拒绝及原因：\n", *id))
385			for _, r := range d.Reasons {
386				sb.WriteString("  - " + r + "\n")
387			}
388			if opts.asJSON {
389				raw, _ := json.MarshalIndent(map[string]any{
390					"allowed": false, "recorded": true, "decision": d,
391				}, "", "  ")
392				fmt.Fprintln(stdout, string(raw))
393			}
394			fmt.Fprint(stderr, sb.String())
395			return 1
396		}
397		human := fmt.Sprintf("允许使用器具 %s，已记录本次申请。\n", *id)
398		return emit(opts, stdout, stderr, human,
399			map[string]any{"allowed": true, "recorded": true, "decision": d})
400	}
401	
402	func cmdReview(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
403		fs := newFlagSet("review", &opts)
404		id := fs.String("id", "", "器具编号")
405		if err := fs.Parse(args); err != nil {
406			fmt.Fprintln(stderr, "review 参数错误：", err)
407			return 2
408		}
409		if strings.TrimSpace(*id) == "" {
410			fmt.Fprintln(stderr, "review 必须提供 --id")
411			return 2
412		}
413		r, err := l.Review(*id)
414		if err != nil {
415			if errors.Is(err, calibrate.ErrNotFound) {
416				return failBusiness(opts, stdout, stderr, err,
417					map[string]any{"found": false, "error": err.Error()})
418			}
419			return failIO(stderr, err)
420		}
421		var sb strings.Builder
422		fmt.Fprintf(&sb, "器具 %s（%s）\n", r.Instrument.ID, r.Instrument.Name)
423		fmt.Fprintf(&sb, "  允许绝对误差：%g；当前状态：%s\n", r.Instrument.AllowedError, r.Instrument.Status)
424		if r.CanUse {
425			sb.WriteString("  当前能否使用：可以\n")
426		} else {
427			sb.WriteString("  当前能否使用：不可以，原因：\n")
428			for _, reason := range r.Reasons {
429				sb.WriteString("    - " + reason + "\n")
430			}
431		}
432		if r.Latest == nil {
433			sb.WriteString("  最近证书：无\n")
434		} else {
435			fmt.Fprintf(&sb, "  最近证书：%s（校准日期 %s，截止日 %s，判定：%s，%s）\n",
436				r.Latest.Number, r.Latest.CalDate, r.Latest.Expiry,
437				verdictText(r.Latest.Pass), expiryText(r.Latest.Expired))
438		}
439		if len(r.History) == 0 {
440			sb.WriteString("  历史证书：无\n")
441		} else {
442			sb.WriteString("  历史证书（按校准日期由近到远）：\n")
443			for _, c := range r.History {
444				fmt.Fprintf(&sb, "    - %s %s 截止 %s 误差 %g %s %s（%s）\n",
445					c.Number, c.CalDate, c.Expiry, c.Error,
446					verdictText(c.Pass), expiryText(c.Expired), c.Method)
447			}
448		}
449		if len(r.Rejections) == 0 {
450			sb.WriteString("  被拒绝的使用记录：无\n")
451		} else {
452			sb.WriteString("  被拒绝的使用记录（原因为申请当时冻结）：\n")
453			for _, u := range r.Rejections {
454				sb.WriteString("    - " + u.RequestedAt + "\n")
455				for _, reason := range u.Reasons {
456					sb.WriteString("        - " + reason + "\n")
457				}
458			}
459		}
460		if len(r.Plans) == 0 {
461			sb.WriteString("  校准计划：无\n")
462		} else {
463			sb.WriteString("  校准计划（含当前及已结束计划、改期记录与关联证书）：\n")
464			for _, p := range r.Plans {
465				head := fmt.Sprintf("    - %s %s 状态：%s", p.Number, p.PlannedDate, p.Status)
466				if p.Open() {
467					head += "（" + p.Marker + "）"
468				}
469				if p.OriginalDate != p.PlannedDate {
470					head += fmt.Sprintf("，最初计划日期 %s", p.OriginalDate)
471				}
472				head += "，说明：" + p.Note + "\n"
473				sb.WriteString(head)
474				for _, ch := range p.Changes {
475					fmt.Fprintf(&sb, "        改期 %s → %s（%s），原因：%s\n",
476						ch.From, ch.To, ch.ChangedAt, ch.Reason)
477				}
478				if p.Status == calibrate.PlanStatusCanceled {
479					fmt.Fprintf(&sb, "        取消于 %s，原因：%s\n", p.CanceledAt, p.CancelReason)
480				}
481				if p.Status == calibrate.PlanStatusDone {
482					fmt.Fprintf(&sb, "        完成于 %s，证书 %s\n", p.CompletedAt, p.CertificateNumber)
483				}
484			}
485		}
486		return emit(opts, stdout, stderr, sb.String(), r)
487	}
488	
489	func verdictText(pass bool) string {
490		if pass {
491			return "合格"
492		}
493		return "超差"
494	}
495	
496	func expiryText(expired bool) string {
497		if expired {
498			return "已到期"
499		}
500		return "未到期"
501	}
502	
503	func cmdList(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
504		fs := newFlagSet("list", &opts)
505		if err := fs.Parse(args); err != nil {
506			fmt.Fprintln(stderr, "list 参数错误：", err)
507			return 2
508		}
509		instruments := l.Instruments()
510		var sb strings.Builder
511		if len(instruments) == 0 {
512			sb.WriteString("台账中还没有器具。\n")
513		}
514		for _, in := range instruments {
515			fmt.Fprintf(&sb, "%s\t%s\t允许误差 %g\t%s\n", in.ID, in.Name, in.AllowedError, in.Status)
516		}
517		return emit(opts, stdout, stderr, sb.String(),
518			map[string]any{"instruments": instruments, "count": len(instruments)})
519	}
520	
521	// failPlanBusiness 是计划类命令共用的业务拒绝输出（退出码 1）。
522	func failPlanBusiness(opts options, stdout, stderr io.Writer, err error, extra map[string]any) int {
523		resp := map[string]any{"accepted": false, "error": err.Error()}
524		for k, v := range extra {
525			resp[k] = v
526		}
527		return failBusiness(opts, stdout, stderr, err, resp)
528	}
529	
530	func cmdPlan(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
531		fs := newFlagSet("plan", &opts)
532		instrument := fs.String("instrument", "", "器具编号")
533		number := fs.String("number", "", "计划编号（全台账唯一，不可复用）")
534		date := fs.String("date", "", "计划日期 YYYY-MM-DD（不早于今天）")
535		note := fs.String("note", "", "非空计划说明")
536		if err := fs.Parse(args); err != nil {
537			fmt.Fprintln(stderr, "plan 参数错误：", err)
538			return 2
539		}
540		missing := []string{}
541		for k, v := range map[string]string{
542			"--instrument": *instrument, "--number": *number, "--date": *date, "--note": *note,
543		} {
544			if strings.TrimSpace(v) == "" {
545				missing = append(missing, k)
546			}
547		}
548		if len(missing) > 0 {
549			fmt.Fprintln(stderr, "plan 缺少必填参数：", strings.Join(missing, "、"))
550			return 2
551		}
552		p, err := l.CreatePlan(calibrate.PlanInput{
553			Number: *number, InstrumentID: *instrument, Date: *date, Note: *note,
554		})
555		if err != nil {
556			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
557				return failPlanBusiness(opts, stdout, stderr, err, nil)
558			}
559			return failIO(stderr, err)
560		}
561		human := fmt.Sprintf("已为器具 %s 建立校准计划 %s，计划日期 %s，说明：%s\n",
562			p.InstrumentID, p.Number, p.PlannedDate, p.Note)
563		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
564	}
565	
566	func cmdReschedule(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
567		fs := newFlagSet("reschedule", &opts)
568		number := fs.String("number", "", "计划编号")
569		date := fs.String("date", "", "新计划日期 YYYY-MM-DD（不早于今天）")
570		reason := fs.String("reason", "", "非空改期原因")
571		if err := fs.Parse(args); err != nil {
572			fmt.Fprintln(stderr, "reschedule 参数错误：", err)
573			return 2
574		}
575		missing := []string{}
576		for k, v := range map[string]string{
577			"--number": *number, "--date": *date, "--reason": *reason,
578		} {
579			if strings.TrimSpace(v) == "" {
580				missing = append(missing, k)
581			}
582		}
583		if len(missing) > 0 {
584			fmt.Fprintln(stderr, "reschedule 缺少必填参数：", strings.Join(missing, "、"))
585			return 2
586		}
587		p, err := l.ReschedulePlan(*number, *date, *reason)
588		if err != nil {
589			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
590				return failPlanBusiness(opts, stdout, stderr, err, nil)
591			}
592			return failIO(stderr, err)
593		}
594		human := fmt.Sprintf("计划 %s 已改期为 %s（第 %d 次改期）。\n",
595			p.Number, p.PlannedDate, len(p.Changes))
596		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
597	}
598	
599	func cmdCancel(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
600		fs := newFlagSet("cancel", &opts)
601		number := fs.String("number", "", "计划编号")
602		reason := fs.String("reason", "", "非空取消原因")
603		if err := fs.Parse(args); err != nil {
604			fmt.Fprintln(stderr, "cancel 参数错误：", err)
605			return 2
606		}
607		if strings.TrimSpace(*number) == "" || strings.TrimSpace(*reason) == "" {
608			fmt.Fprintln(stderr, "cancel 必须提供 --number、--reason")
609			return 2
610		}
611		p, err := l.CancelPlan(*number, *reason)
612		if err != nil {
613			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
614				return failPlanBusiness(opts, stdout, stderr, err, nil)
615			}
616			return failIO(stderr, err)
617		}
618		human := fmt.Sprintf("计划 %s 已于 %s 取消，原因：%s；不再列入待办。\n",
619			p.Number, p.CanceledAt, p.CancelReason)
620		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
621	}
622	
623	func cmdComplete(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
624		fs := newFlagSet("complete", &opts)
625		number := fs.String("number", "", "计划编号")
626		certificate := fs.String("certificate", "", "证书编号")
627		if err := fs.Parse(args); err != nil {
628			fmt.Fprintln(stderr, "complete 参数错误：", err)
629			return 2
630		}
631		if strings.TrimSpace(*number) == "" || strings.TrimSpace(*certificate) == "" {
632			fmt.Fprintln(stderr, "complete 必须提供 --number、--certificate")
633			return 2
634		}
635		p, idempotent, err := l.CompletePlan(*number, *certificate)
636		if err != nil {
637			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
638				return failPlanBusiness(opts, stdout, stderr, err, nil)
639			}
640			return failIO(stderr, err)
641		}
642		note := "已完成"
643		if idempotent {
644			note = "该计划已由此证书完成，返回原结果，未刷新完成时间"
645		}
646		human := fmt.Sprintf("%s：计划 %s，证书 %s，完成时间 %s。\n",
647			note, p.Number, p.CertificateNumber, p.CompletedAt)
648		return emit(opts, stdout, stderr, human,
649			map[string]any{"accepted": true, "idempotent": idempotent, "plan": p})
650	}
651	
652	func cmdTodos(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
653		fs := newFlagSet("todos", &opts)
654		instrument := fs.String("instrument", "", "只看该器具编号的待办")
655		if err := fs.Parse(args); err != nil {
656			fmt.Fprintln(stderr, "todos 参数错误：", err)
657			return 2
658		}
659		items, err := l.Todos(*instrument)
660		if err != nil {
661			if errors.Is(err, calibrate.ErrNotFound) {
662				return failBusiness(opts, stdout, stderr, err,
663					map[string]any{"found": false, "error": err.Error()})
664			}
665			return failIO(stderr, err)
666		}
667		var sb strings.Builder
668		if len(items) == 0 {
669			sb.WriteString("无待办。\n")
670		}
671		for _, it := range items {
672			fmt.Fprintf(&sb, "%s\t%s（%s，%s）\t%s\t%s\t%s\n",
673				it.PlanNumber, it.InstrumentID, it.InstrumentName, it.Status,
674				it.PlannedDate, it.Marker, it.Note)
675		}
676		return emit(opts, stdout, stderr, sb.String(),
677			map[string]any{"todos": items, "count": len(items)})
678	}
