func TestQueriesDoNotRecordAndEmptyStaysEmpty(t *testing.T) {
	clock := &fakeClock{t: mustDate(t, "2026-10-02")}
	l := newTestLedger(t, clock)
	mustRegister(t, l, "M-1", "万用表", 0.5)

	if recs := l.UsageRecords(); len(recs) != 0 {
