	}
	if _, err := l.CanUse("M-1"); err != nil {
		t.Fatalf("can use: %v", err)
	}
	if _, err := l.Review("M-1"); err != nil {
		t.Fatalf("review: %v", err)
	}
	if recs := l.UsageRecords(); len(recs) != 0 {
		t.Fatalf("查询本身不应新增申请，得到 %d 条", len(recs))
	}
